17 
18 module dm_csrs #(
19   parameter int unsigned        NrHarts          = 1,
20   parameter int unsigned        BusWidth         = 32,
21   parameter logic [NrHarts-1:0] SelectableHarts  = {NrHarts{1'b1}}
22 ) (
23   input  logic                              clk_i,           // Clock
24   input  logic                              rst_ni,          // Asynchronous reset active low
25   input  logic                              testmode_i,
26   input  logic                              dmi_rst_ni,      // Debug Module Intf reset active-low
27   input  logic                              dmi_req_valid_i,
28   output logic                              dmi_req_ready_o,
29   input  dm::dmi_req_t                      dmi_req_i,
30   // every request needs a response one cycle later
31   output logic                              dmi_resp_valid_o,
32   input  logic                              dmi_resp_ready_i,
33   output dm::dmi_resp_t                     dmi_resp_o,
34   // global ctrl
35   output logic                              ndmreset_o,      // non-debug module reset active-high
36   output logic                              dmactive_o,      // 1 -> debug-module is active,
37                                                              // 0 -> synchronous re-set
38   // hart status
39   input  dm::hartinfo_t [NrHarts-1:0]       hartinfo_i,      // static hartinfo
40   input  logic [NrHarts-1:0]                halted_i,        // hart is halted
41   input  logic [NrHarts-1:0]                unavailable_i,   // e.g.: powered down
42   input  logic [NrHarts-1:0]                resumeack_i,     // hart acknowledged resume request
43   // hart control
44   output logic [19:0]                       hartsel_o,       // hartselect to ctrl module
45   output logic [NrHarts-1:0]                haltreq_o,       // request to halt a hart
46   output logic [NrHarts-1:0]                resumereq_o,     // request hart to resume
47   output logic                              clear_resumeack_o,
48 
49   output logic                              cmd_valid_o,       // debugger writing to cmd field
50   output dm::command_t                      cmd_o,             // abstract command
51   input  logic                              cmderror_valid_i,  // an error occurred
52   input  dm::cmderr_e                       cmderror_i,        // this error occurred
53   input  logic                              cmdbusy_i,         // cmd is currently busy executing
54 
55   output logic [dm::ProgBufSize-1:0][31:0]  progbuf_o, // to system bus
56   output logic [dm::DataCount-1:0][31:0]    data_o,
57 
58   input  logic [dm::DataCount-1:0][31:0]    data_i,
59   input  logic                              data_valid_i,
60   // system bus access module (SBA)
61   output logic [BusWidth-1:0]               sbaddress_o,
62   input  logic [BusWidth-1:0]               sbaddress_i,
63   output logic                              sbaddress_write_valid_o,
64   // control signals in
65   output logic                              sbreadonaddr_o,
66   output logic                              sbautoincrement_o,
67   output logic [2:0]                        sbaccess_o,
68   // data out
69   output logic                              sbreadondata_o,
70   output logic [BusWidth-1:0]               sbdata_o,
71   output logic                              sbdata_read_valid_o,
72   output logic                              sbdata_write_valid_o,
73   // read data in
74   input  logic [BusWidth-1:0]               sbdata_i,
75   input  logic                              sbdata_valid_i,
76   // control signals
77   input  logic                              sbbusy_i,
78   input  logic                              sberror_valid_i, // bus error occurred
79   input  logic [2:0]                        sberror_i // bus error occurred
80 );
81   // the amount of bits we need to represent all harts
82   localparam int unsigned HartSelLen = (NrHarts == 1) ? 1 : $clog2(NrHarts);
83   localparam int unsigned NrHartsAligned = 2**HartSelLen;
84 
85   dm::dtm_op_e dtm_op;
86   assign dtm_op = dm::dtm_op_e'(dmi_req_i.op);
87 
88   logic        resp_queue_full;
89   logic        resp_queue_empty;
90   logic        resp_queue_push;
91   logic        resp_queue_pop;
92   logic [31:0] resp_queue_data;
93 
94   localparam dm::dm_csr_e DataEnd = dm::dm_csr_e'(dm::Data0 + {4'b0, dm::DataCount} - 8'h01);
95   localparam dm::dm_csr_e ProgBufEnd = dm::dm_csr_e'(dm::ProgBuf0 + {4'b0, dm::ProgBufSize} - 8'h01);
96 
97   logic [31:0] haltsum0, haltsum1, haltsum2, haltsum3;
98   logic [((NrHarts-1)/2**5 + 1) * 32 - 1 : 0] halted;
99   logic [(NrHarts-1)/2**5:0][31:0] halted_reshaped0;
100   logic [NrHarts/2**10:0][31:0] halted_reshaped1;
101   logic [NrHarts/2**15:0][31:0] halted_reshaped2;
102   logic [(NrHarts/2**10+1)*32-1:0] halted_flat1;
103   logic [(NrHarts/2**15+1)*32-1:0] halted_flat2;
104   logic [32-1:0] halted_flat3;
105 
106   // haltsum0
107   logic [14:0] hartsel_idx0;
108   always_comb begin : p_haltsum0
109     halted              = '0;
110     haltsum0            = '0;
111     hartsel_idx0        = hartsel_o[19:5];
112     halted[NrHarts-1:0] = halted_i;
113     halted_reshaped0    = halted;
114     if (hartsel_idx0 < 15'((NrHarts-1)/2**5+1)) begin
115       haltsum0 = halted_reshaped0[hartsel_idx0];
116     end
117   end
118 
119   // haltsum1
120   logic [9:0] hartsel_idx1;
121   always_comb begin : p_reduction1
122     halted_flat1 = '0;
123     haltsum1     = '0;
124     hartsel_idx1 = hartsel_o[19:10];
125 
126     for (int unsigned k = 0; k < NrHarts/2**5+1; k++) begin
127       halted_flat1[k] = |halted_reshaped0[k];
128     end
129     halted_reshaped1 = halted_flat1;
130 
131     if (hartsel_idx1 < 10'((NrHarts/2**10+1))) begin
132       haltsum1 = halted_reshaped1[hartsel_idx1];
133     end
134   end
135 
136   // haltsum2
137   logic [4:0] hartsel_idx2;
138   always_comb begin : p_reduction2
139     halted_flat2 = '0;
140     haltsum2     = '0;
141     hartsel_idx2 = hartsel_o[19:15];
142 
143     for (int unsigned k = 0; k < NrHarts/2**10+1; k++) begin
144       halted_flat2[k] = |halted_reshaped1[k];
145     end
146     halted_reshaped2 = halted_flat2;
147 
148     if (hartsel_idx2 < 5'((NrHarts/2**15+1))) begin
149       haltsum2         = halted_reshaped2[hartsel_idx2];
150     end
151   end
152 
153   // haltsum3
154   always_comb begin : p_reduction3
155     halted_flat3 = '0;
156     for (int unsigned k = 0; k < NrHarts/2**15+1; k++) begin
157       halted_flat3[k] = |halted_reshaped2[k];
158     end
159     haltsum3 = halted_flat3;
160   end
161 
162 
163   dm::dmstatus_t      dmstatus;
164   dm::dmcontrol_t     dmcontrol_d, dmcontrol_q;
165   dm::abstractcs_t    abstractcs;
166   dm::cmderr_e        cmderr_d, cmderr_q;
167   dm::command_t       command_d, command_q;
168   logic               cmd_valid_d, cmd_valid_q;
169   dm::abstractauto_t  abstractauto_d, abstractauto_q;
170   dm::sbcs_t          sbcs_d, sbcs_q;
171   logic [63:0]        sbaddr_d, sbaddr_q;
172   logic [63:0]        sbdata_d, sbdata_q;
173 
174   logic [NrHarts-1:0] havereset_d, havereset_q;
175   // program buffer
176   logic [dm::ProgBufSize-1:0][31:0] progbuf_d, progbuf_q;
177   logic [dm::DataCount-1:0][31:0] data_d, data_q;
178 
179   logic [HartSelLen-1:0] selected_hart;
180 
181   // a successful response returns zero
182   assign dmi_resp_o.resp = dm::DTM_SUCCESS;
183   assign dmi_resp_valid_o     = ~resp_queue_empty;
184   assign dmi_req_ready_o      = ~resp_queue_full;
185   assign resp_queue_push      = dmi_req_valid_i & dmi_req_ready_o;
186   // SBA
187   assign sbautoincrement_o = sbcs_q.sbautoincrement;
188   assign sbreadonaddr_o    = sbcs_q.sbreadonaddr;
189   assign sbreadondata_o    = sbcs_q.sbreadondata;
190   assign sbaccess_o        = sbcs_q.sbaccess;
191   assign sbdata_o          = sbdata_q[BusWidth-1:0];
192   assign sbaddress_o       = sbaddr_q[BusWidth-1:0];
193 
194   assign hartsel_o         = {dmcontrol_q.hartselhi, dmcontrol_q.hartsello};
195 
196   // needed to avoid lint warnings
197   logic [NrHartsAligned-1:0] havereset_d_aligned, havereset_q_aligned,
198                              resumeack_aligned, unavailable_aligned,
199                              halted_aligned;
200   assign resumeack_aligned   = NrHartsAligned'(resumeack_i);
201   assign unavailable_aligned = NrHartsAligned'(unavailable_i);
202   assign halted_aligned      = NrHartsAligned'(halted_i);
203 
204   assign havereset_d         = NrHarts'(havereset_d_aligned);
205   assign havereset_q_aligned = NrHartsAligned'(havereset_q);
206 
207   dm::hartinfo_t [NrHartsAligned-1:0] hartinfo_aligned;
208   always_comb begin : p_hartinfo_align
209     hartinfo_aligned = '0;
210     hartinfo_aligned[NrHarts-1:0] = hartinfo_i;
211   end
212 
213   // helper variables
214   dm::sbcs_t sbcs;
215   dm::dmcontrol_t dmcontrol;
216   dm::abstractcs_t a_abstractcs;
217   logic [4:0] autoexecdata_idx;
218   always_comb begin : csr_read_write
219     // --------------------
220     // Static Values (R/O)
221     // --------------------
222     // dmstatus
223     dmstatus    = '0;
224     dmstatus.version = dm::DbgVersion013;
225     // no authentication implemented
226     dmstatus.authenticated = 1'b1;
227     // we do not support halt-on-reset sequence
228     dmstatus.hasresethaltreq = 1'b0;
229     // TODO(zarubaf) things need to change here if we implement the array mask
230     dmstatus.allhavereset = havereset_q_aligned[selected_hart];
231     dmstatus.anyhavereset = havereset_q_aligned[selected_hart];
232 
233     dmstatus.allresumeack = resumeack_aligned[selected_hart];
234     dmstatus.anyresumeack = resumeack_aligned[selected_hart];
235 
236     dmstatus.allunavail   = unavailable_aligned[selected_hart];
237     dmstatus.anyunavail   = unavailable_aligned[selected_hart];
238 
239     // as soon as we are out of the legal Hart region tell the debugger
240     // that there are only non-existent harts
241     dmstatus.allnonexistent = logic'(32'(hartsel_o) > (NrHarts - 1));
242     dmstatus.anynonexistent = logic'(32'(hartsel_o) > (NrHarts - 1));
243 
244     // We are not allowed to be in multiple states at once. This is a to
245     // make the running/halted and unavailable states exclusive.
246     dmstatus.allhalted    = halted_aligned[selected_hart] & ~unavailable_aligned[selected_hart];
247     dmstatus.anyhalted    = halted_aligned[selected_hart] & ~unavailable_aligned[selected_hart];
248 
249     dmstatus.allrunning   = ~halted_aligned[selected_hart] & ~unavailable_aligned[selected_hart];
250     dmstatus.anyrunning   = ~halted_aligned[selected_hart] & ~unavailable_aligned[selected_hart];
251 
252     // abstractcs
253     abstractcs = '0;
254     abstractcs.datacount = dm::DataCount;
255     abstractcs.progbufsize = dm::ProgBufSize;
256     abstractcs.busy = cmdbusy_i;
257     abstractcs.cmderr = cmderr_q;
258 
259     // abstractautoexec
260     abstractauto_d = abstractauto_q;
261     abstractauto_d.zero0 = '0;
262 
263     // default assignments
264     havereset_d_aligned = NrHartsAligned'(havereset_q);
265     dmcontrol_d         = dmcontrol_q;
266     cmderr_d            = cmderr_q;
267     command_d           = command_q;
268     progbuf_d           = progbuf_q;
269     data_d              = data_q;
270     sbcs_d              = sbcs_q;
271     sbaddr_d            = 64'(sbaddress_i);
272     sbdata_d            = sbdata_q;
273 
274     resp_queue_data         = 32'b0;
275     cmd_valid_d             = 1'b0;
276     sbaddress_write_valid_o = 1'b0;
277     sbdata_read_valid_o     = 1'b0;
278     sbdata_write_valid_o    = 1'b0;
279     clear_resumeack_o       = 1'b0;
280 
281     // helper variables
282     sbcs         = '0;
283     dmcontrol    = '0;
284     a_abstractcs = '0;
285 
286     autoexecdata_idx    = dmi_req_i.addr[4:0] - 5'(dm::Data0);
287 
288     // localparam int unsigned DataCountAlign = $clog2(dm::DataCount);
289     // reads
290     if (dmi_req_ready_o && dmi_req_valid_i && dtm_op == dm::DTM_READ) begin
291       unique case ({1'b0, dmi_req_i.addr}) inside
292         [(dm::Data0):DataEnd]: begin
293           // logic [$clog2(dm::DataCount)-1:0] resp_queue_idx;
294           // resp_queue_idx = dmi_req_i.addr[4:0] - int'(dm::Data0);
295           resp_queue_data = data_q[$clog2(dm::DataCount)'(autoexecdata_idx)];
296           if (!cmdbusy_i) begin
297             // check whether we need to re-execute the command (just give a cmd_valid)
298             if (autoexecdata_idx < $bits(abstractauto_q.autoexecdata)) begin
299               cmd_valid_d = abstractauto_q.autoexecdata[autoexecdata_idx];
300             end
301           end
302         end
303         dm::DMControl:    resp_queue_data = dmcontrol_q;
304         dm::DMStatus:     resp_queue_data = dmstatus;
305         dm::Hartinfo:     resp_queue_data = hartinfo_aligned[selected_hart];
306         dm::AbstractCS:   resp_queue_data = abstractcs;
307         dm::AbstractAuto: resp_queue_data = abstractauto_q;
308         // command is read-only
309         dm::Command:    resp_queue_data = '0;
310         [(dm::ProgBuf0):ProgBufEnd]: begin
311           resp_queue_data = progbuf_q[dmi_req_i.addr[$clog2(dm::ProgBufSize)-1:0]];
312           if (!cmdbusy_i) begin
313             // check whether we need to re-execute the command (just give a cmd_valid)
314             // range of autoexecprogbuf is 31:16
315             cmd_valid_d = abstractauto_q.autoexecprogbuf[{1'b1, dmi_req_i.addr[3:0]}];
316           end
317         end
318         dm::HaltSum0: resp_queue_data = haltsum0;
319         dm::HaltSum1: resp_queue_data = haltsum1;
320         dm::HaltSum2: resp_queue_data = haltsum2;
321         dm::HaltSum3: resp_queue_data = haltsum3;
322         dm::SBCS: begin
323           resp_queue_data = sbcs_q;
324         end
325         dm::SBAddress0: begin
326           // access while the SBA was busy
327           if (sbbusy_i) begin
328             sbcs_d.sbbusyerror = 1'b1;
329           end else begin
330             resp_queue_data = sbaddr_q[31:0];
331           end
332         end
333         dm::SBAddress1: begin
334           // access while the SBA was busy
335           if (sbbusy_i) begin
336             sbcs_d.sbbusyerror = 1'b1;
337           end else begin
338             resp_queue_data = sbaddr_q[63:32];
339           end
340         end
341         dm::SBData0: begin
342           // access while the SBA was busy
343           if (sbbusy_i) begin
344             sbcs_d.sbbusyerror = 1'b1;
345           end else begin
346             sbdata_read_valid_o = (sbcs_q.sberror == '0);
347             resp_queue_data = sbdata_q[31:0];
348           end
349         end
350         dm::SBData1: begin
351           // access while the SBA was busy
352           if (sbbusy_i) begin
353             sbcs_d.sbbusyerror = 1'b1;
354           end else begin
355             resp_queue_data = sbdata_q[63:32];
356           end
357         end
358         default:;
359       endcase
360     end
361 
362     // write
363     if (dmi_req_ready_o && dmi_req_valid_i && dtm_op == dm::DTM_WRITE) begin
364       unique case (dm::dm_csr_e'({1'b0, dmi_req_i.addr})) inside
365         [(dm::Data0):DataEnd]: begin
366           // attempts to write them while busy is set does not change their value
367           if (!cmdbusy_i && dm::DataCount > 0) begin
368             data_d[dmi_req_i.addr[$clog2(dm::DataCount)-1:0]] = dmi_req_i.data;
369             // check whether we need to re-execute the command (just give a cmd_valid)
370             if (autoexecdata_idx < $bits(abstractauto_q.autoexecdata)) begin
371               cmd_valid_d = abstractauto_q.autoexecdata[autoexecdata_idx];
372             end
373           end
374         end
375         dm::DMControl: begin
376           dmcontrol = dm::dmcontrol_t'(dmi_req_i.data);
377           // clear the havreset of the selected hart
378           if (dmcontrol.ackhavereset) begin
379             havereset_d_aligned[selected_hart] = 1'b0;
380           end
381           dmcontrol_d = dmi_req_i.data;
382         end
383         dm::DMStatus:; // write are ignored to R/O register
384         dm::Hartinfo:; // hartinfo is R/O
385         // only command error is write-able
386         dm::AbstractCS: begin // W1C
387           // Gets set if an abstract command fails. The bits in this
388           // field remain set until they are cleared by writing 1 to
389           // them. No abstract command is started until the value is
390           // reset to 0.
391           a_abstractcs = dm::abstractcs_t'(dmi_req_i.data);
392           // reads during abstract command execution are not allowed
393           if (!cmdbusy_i) begin
394             cmderr_d = dm::cmderr_e'(~a_abstractcs.cmderr & cmderr_q);
395           end else if (cmderr_q == dm::CmdErrNone) begin
396             cmderr_d = dm::CmdErrBusy;
397           end
398         end
399         dm::Command: begin
400           // writes are ignored if a command is already busy
401           if (!cmdbusy_i) begin
402             cmd_valid_d = 1'b1;
403             command_d = dm::command_t'(dmi_req_i.data);
404           // if there was an attempted to write during a busy execution
405           // and the cmderror field is zero set the busy error
406           end else if (cmderr_q == dm::CmdErrNone) begin
407             cmderr_d = dm::CmdErrBusy;
408           end
409         end
410         dm::AbstractAuto: begin
411           // this field can only be written legally when there is no command executing
412           if (!cmdbusy_i) begin
413             abstractauto_d                 = 32'b0;
414             abstractauto_d.autoexecdata    = 12'(dmi_req_i.data[dm::DataCount-1:0]);
415             abstractauto_d.autoexecprogbuf = 16'(dmi_req_i.data[dm::ProgBufSize-1+16:16]);
416           end else if (cmderr_q == dm::CmdErrNone) begin
417             cmderr_d = dm::CmdErrBusy;
418           end
419         end
420         [(dm::ProgBuf0):ProgBufEnd]: begin
421           // attempts to write them while busy is set does not change their value
422           if (!cmdbusy_i) begin
423             progbuf_d[dmi_req_i.addr[$clog2(dm::ProgBufSize)-1:0]] = dmi_req_i.data;
424             // check whether we need to re-execute the command (just give a cmd_valid)
425             // this should probably throw an error if executed during another command
426             // was busy
427             // range of autoexecprogbuf is 31:16
428             cmd_valid_d = abstractauto_q.autoexecprogbuf[{1'b1, dmi_req_i.addr[3:0]}];
429           end
430         end
431         dm::SBCS: begin
432           // access while the SBA was busy
433           if (sbbusy_i) begin
434             sbcs_d.sbbusyerror = 1'b1;
435           end else begin
436             sbcs = dm::sbcs_t'(dmi_req_i.data);
437             sbcs_d = sbcs;
438             // R/W1C
439             sbcs_d.sbbusyerror = sbcs_q.sbbusyerror & (~sbcs.sbbusyerror);
440             sbcs_d.sberror     = sbcs_q.sberror     & (~sbcs.sberror);
441           end
442         end
443         dm::SBAddress0: begin
444           // access while the SBA was busy
445           if (sbbusy_i) begin
446             sbcs_d.sbbusyerror = 1'b1;
447           end else begin
448             sbaddr_d[31:0] = dmi_req_i.data;
449             sbaddress_write_valid_o = (sbcs_q.sberror == '0);
450           end
451         end
452         dm::SBAddress1: begin
453           // access while the SBA was busy
454           if (sbbusy_i) begin
455             sbcs_d.sbbusyerror = 1'b1;
456           end else begin
457             sbaddr_d[63:32] = dmi_req_i.data;
458           end
459         end
460         dm::SBData0: begin
461           // access while the SBA was busy
462           if (sbbusy_i) begin
463            sbcs_d.sbbusyerror = 1'b1;
464           end else begin
465             sbdata_d[31:0] = dmi_req_i.data;
466             sbdata_write_valid_o = (sbcs_q.sberror == '0);
467           end
468         end
469         dm::SBData1: begin
470           // access while the SBA was busy
471           if (sbbusy_i) begin
472            sbcs_d.sbbusyerror = 1'b1;
473           end else begin
474             sbdata_d[63:32] = dmi_req_i.data;
475           end
476         end
477         default:;
478       endcase
479     end
480     // hart threw a command error and has precedence over bus writes
481     if (cmderror_valid_i) begin
482       cmderr_d = cmderror_i;
483     end
484 
485     // update data registers
486     if (data_valid_i) begin
487       data_d = data_i;
488     end
489 
490     // set the havereset flag when we did a ndmreset
491     if (ndmreset_o) begin
492       havereset_d_aligned[NrHarts-1:0] = '1;
493     end
494     // -------------
495     // System Bus
496     // -------------
497     // set bus error
498     if (sberror_valid_i) begin
499       sbcs_d.sberror = sberror_i;
500     end
501     // update read data
502     if (sbdata_valid_i) begin
503       sbdata_d = 64'(sbdata_i);
504     end
505 
506     // dmcontrol
507     // TODO(zarubaf) we currently do not implement the hartarry mask
508     dmcontrol_d.hasel           = 1'b0;
509     // we do not support resetting an individual hart
510     dmcontrol_d.hartreset       = 1'b0;
511     dmcontrol_d.setresethaltreq = 1'b0;
512     dmcontrol_d.clrresethaltreq = 1'b0;
513     dmcontrol_d.zero1           = '0;
514     dmcontrol_d.zero0           = '0;
515     // Non-writeable, clear only
516     dmcontrol_d.ackhavereset    = 1'b0;
517     if (!dmcontrol_q.resumereq && dmcontrol_d.resumereq) begin
518       clear_resumeack_o = 1'b1;
519     end
520     if (dmcontrol_q.resumereq && resumeack_i) begin
521       dmcontrol_d.resumereq = 1'b0;
522     end
523     // static values for dcsr
524     sbcs_d.sbversion            = 3'b1;
525     sbcs_d.sbbusy               = sbbusy_i;
526     sbcs_d.sbasize              = $bits(sbcs_d.sbasize)'(BusWidth);
527     sbcs_d.sbaccess128          = 1'b0;
528     sbcs_d.sbaccess64           = logic'(BusWidth == 32'd64);
529     sbcs_d.sbaccess32           = logic'(BusWidth == 32'd32);
530     sbcs_d.sbaccess16           = 1'b0;
531     sbcs_d.sbaccess8            = 1'b0;
