561   ) i_fifo (
562     .clk_i            ( clk_i                ),
563     .rst_ni           ( dmi_rst_ni           ), // reset only when system is re-set
564     .flush_i          ( 1'b0                 ), // we do not need to flush this queue
565     .testmode_i       ( testmode_i           ),
566     .full_o           ( resp_queue_full      ),
567     .empty_o          ( resp_queue_empty     ),
568     .alm_full_o       (                      ),
569     .alm_empty_o      (                      ),
