576   always_ff @(posedge clk_i or negedge rst_ni) begin : p_regs
577     // PoR
578     if (!rst_ni) begin
579       dmcontrol_q    <= '0;
580       // this is the only write-able bit during reset
581       cmderr_q       <= dm::CmdErrNone;
582       command_q      <= '0;
583       abstractauto_q <= '0;
584       progbuf_q      <= '0;
585       data_q         <= '0;
586       sbcs_q         <= '0;
587       sbaddr_q       <= '0;
588       sbdata_q       <= '0;
589       havereset_q    <= '1;
