591       havereset_q    <= SelectableHarts & havereset_d;
592       // synchronous re-set of debug module, active-low, except for dmactive
593       if (!dmcontrol_q.dmactive) begin
594         dmcontrol_q.haltreq          <= '0;
595         dmcontrol_q.resumereq        <= '0;
596         dmcontrol_q.hartreset        <= '0;
597         dmcontrol_q.ackhavereset     <= '0;
598         dmcontrol_q.zero1            <= '0;
599         dmcontrol_q.hasel            <= '0;
