601         dmcontrol_q.hartselhi        <= '0;
602         dmcontrol_q.zero0            <= '0;
603         dmcontrol_q.setresethaltreq  <= '0;
604         dmcontrol_q.clrresethaltreq  <= '0;
605         dmcontrol_q.ndmreset         <= '0;
606         // this is the only write-able bit during reset
607         dmcontrol_q.dmactive         <= dmcontrol_d.dmactive;
608         cmderr_q                     <= dm::CmdErrNone;
609         command_q                    <= '0;
